    def maximumStrength(self, nums: List[int], k: int) -> int:
        n = len(nums)

        # Precompute prefix sums
        prefix = [0] * (n + 1)
        for i in range(n):
            prefix[i + 1] = prefix[i] + nums[i]

        # dp[j][i] = maximum strength using j subarrays in first i elements
        # We'll use a 2D DP but optimize the transitions
        INF = float('-inf')
        dp = [[INF] * (n + 1) for _ in range(k + 1)]
        dp[0][0] = 0

        for i in range(n):
