                    coeff = (k - j + 1) * ((-1) ** (j + 1))
                    # Try all possible starting positions for this subarray
                    for start in range(i + 1):
                        sub_sum = prefix[i + 1] - prefix[start]
                        if dp[j - 1][start] != INF:
