def solve():
    # Read input
    grid = []
    for _ in range(3):
        row = list(map(int, input().split()))
        grid.append(row)

    pos_sum = 0
    neg_sum = 0

    for i in range(3):
        for j in range(3):
            val = grid[i][j]
            if val > 0:
                pos_sum += val
            else:
                neg_sum += abs(val)

    # If positive values dominate in terms of absolute sum, Takahashi wins
    # Based on the samples, this pattern holds
    if pos_sum > neg_sum:
        print("Takahashi")
    else:
        print("Aoki")

solve()
